17	package org.apache.kafka.server;
18	
19	import kafka.log.LogManager;
20	import kafka.server.KafkaBroker;
21	
22	import org.apache.kafka.clients.admin.Admin;
23	import org.apache.kafka.clients.admin.AlterConfigOp;
24	import org.apache.kafka.clients.admin.ConfigEntry;
25	import org.apache.kafka.clients.admin.LogDirDescription;
26	import org.apache.kafka.clients.admin.NewPartitionReassignment;
27	import org.apache.kafka.clients.admin.NewPartitions;
28	import org.apache.kafka.clients.admin.NewTopic;
29	import org.apache.kafka.clients.admin.TopicDescription;
30	import org.apache.kafka.common.TopicPartition;
31	import org.apache.kafka.common.TopicPartitionInfo;
32	import org.apache.kafka.common.TopicPartitionReplica;
33	import org.apache.kafka.common.Uuid;
34	import org.apache.kafka.common.config.ConfigResource;
35	import org.apache.kafka.common.errors.IneligibleReplicaException;
36	import org.apache.kafka.common.errors.InvalidConfigurationException;
37	import org.apache.kafka.common.errors.InvalidReplicaAssignmentException;
38	import org.apache.kafka.common.errors.InvalidReplicationFactorException;
39	import org.apache.kafka.common.errors.InvalidRequestException;
40	import org.apache.kafka.common.test.ClusterInstance;
41	import org.apache.kafka.common.test.api.ClusterConfigProperty;
42	import org.apache.kafka.common.test.api.ClusterTest;
43	import org.apache.kafka.common.test.api.ClusterTestDefaults;
44	import org.apache.kafka.common.test.api.Type;
45	import org.apache.kafka.common.utils.Sanitizer;
46	import org.apache.kafka.server.common.MetadataVersion;
47	import org.apache.kafka.server.config.ServerLogConfigs;
48	import org.apache.kafka.server.metrics.KafkaYammerMetrics;
49	import org.apache.kafka.storage.internals.log.UnifiedLog;
50	import org.apache.kafka.test.TestUtils;
51	
52	import com.yammer.metrics.core.Gauge;
53	import com.yammer.metrics.core.MetricName;
54	
55	import java.util.ArrayList;
56	import java.util.Collection;
57	import java.util.HashSet;
58	import java.util.List;
59	import java.util.Map;
60	import java.util.Optional;
61	import java.util.Set;
62	import java.util.concurrent.ExecutionException;
63	import java.util.stream.Collectors;
64	
65	import scala.Option;
66	
67	import static org.junit.jupiter.api.Assertions.assertEquals;
68	import static org.junit.jupiter.api.Assertions.assertFalse;
69	import static org.junit.jupiter.api.Assertions.assertInstanceOf;
70	import static org.junit.jupiter.api.Assertions.assertThrows;
71	import static org.junit.jupiter.api.Assertions.assertTrue;
72	
73	@ClusterTestDefaults(types = {Type.KRAFT}, brokers = 3, disksPerBroker = 2)
74	public class CordonedLogDirsIntegrationTest {
75	
76	    private static final long WAIT_MS = 60_000;
77	
78	    private final ClusterInstance cluster;
79	    private int topicCounter = 0;
80	
81	    CordonedLogDirsIntegrationTest(ClusterInstance cluster) {
82	        this.cluster = cluster;
83	    }
84	
85	    private String newTopicName() {
86	        return "topic-" + topicCounter++;
87	    }
88	
89	    private static ConfigResource broker(int brokerId) {
90	        return new ConfigResource(ConfigResource.Type.BROKER, String.valueOf(brokerId));
91	    }
92	
93	    private static void setCordoned(Admin admin, int brokerId, String value) throws Exception {
94	        admin.incrementalAlterConfigs(Map.of(broker(brokerId), List.of(new AlterConfigOp(
95	            new ConfigEntry(ServerLogConfigs.CORDONED_LOG_DIRS_CONFIG, value), AlterConfigOp.OpType.SET)))).all().get();
96	    }
97	
98	    private static void uncordon(Admin admin, int brokerId) throws Exception {
99	        admin.incrementalAlterConfigs(Map.of(broker(brokerId), List.of(new AlterConfigOp(
100	            new ConfigEntry(ServerLogConfigs.CORDONED_LOG_DIRS_CONFIG, null), AlterConfigOp.OpType.DELETE)))).all().get();
101	    }
102	
103	    private static Map<String, LogDirDescription> logDirs(Admin admin, int brokerId) throws Exception {
104	        return admin.describeLogDirs(List.of(brokerId)).allDescriptions().get().get(brokerId);
105	    }
106	
107	    private static List<String> sortedLogDirs(Admin admin, int brokerId) throws Exception {
108	        return logDirs(admin, brokerId).keySet().stream().sorted().toList();
109	    }
110	
111	    private static Set<String> cordonedLogDirs(Admin admin, int brokerId) throws Exception {
112	        return logDirs(admin, brokerId).entrySet().stream()
113	            .filter(e -> e.getValue().isCordoned())
114	            .map(Map.Entry::getKey)
115	            .collect(Collectors.toSet());
116	    }
117	
118	    private static void waitForCordoned(Admin admin, int brokerId, Set<String> expected) throws Exception {
119	        TestUtils.waitForCondition(() -> expected.equals(cordonedLogDirs(admin, brokerId)), WAIT_MS,
120	            "Broker " + brokerId + " did not report the cordoned log directories " + expected);
121	    }
122	
123	    private static Throwable createTopicError(Admin admin, NewTopic topic) throws Exception {
124	        try {
125	            admin.createTopics(List.of(topic)).all().get();
126	            return null;
127	        } catch (ExecutionException e) {
128	            return e.getCause();
129	        }
130	    }
131	
132	    private static Set<Integer> replicaBrokers(Admin admin, String topic) throws Exception {
133	        TopicDescription description = admin.describeTopics(List.of(topic)).allTopicNames().get().get(topic);
134	        Set<Integer> brokers = new HashSet<>();
135	        for (TopicPartitionInfo partition : description.partitions()) {
136	            partition.replicas().forEach(node -> brokers.add(node.id()));
137	        }
138	        return brokers;
139	    }
140	
141	    /**
142	     * Waits until the controller refuses to place a replica on the given fully cordoned broker, which
143	     * means that it has seen the cordoned directories reported in the heartbeats of the broker.
144	     */
145	    private void waitForControllerToExcludeBroker(Admin admin, int brokerCount) throws Exception {
146	        TestUtils.waitForCondition(() ->
147	            createTopicError(admin, new NewTopic(newTopicName(), 1, (short) brokerCount)) instanceof InvalidReplicationFactorException,
148	            WAIT_MS, "The controller kept placing replicas on the cordoned broker");
149	    }
150	
151	    private static <T extends Throwable> void assertCause(Class<T> expected, org.junit.jupiter.api.function.Executable executable) {
152	        ExecutionException e = assertThrows(ExecutionException.class, executable);
153	        assertInstanceOf(expected, e.getCause());
154	    }
155	
156	    @ClusterTest
157	    public void testCordonedLogDirectoriesAreNotUsedForNewPartitions() throws Exception {
158	        try (Admin admin = cluster.admin()) {
159	            // Cordon the first directory of every broker.
160	            Map<Integer, String> cordoned = new java.util.HashMap<>();
161	            for (int brokerId : cluster.brokerIds()) {
162	                String dir = sortedLogDirs(admin, brokerId).get(0);
163	                cordoned.put(brokerId, dir);
164	                setCordoned(admin, brokerId, dir);
165	            }
166	            for (Map.Entry<Integer, String> entry : cordoned.entrySet()) {
167	                waitForCordoned(admin, entry.getKey(), Set.of(entry.getValue()));
168	            }
169	
170	            String topic = newTopicName();
171	            admin.createTopics(List.of(new NewTopic(topic, 6, (short) 3))).all().get();
172	            cluster.waitTopicCreation(topic, 6);
173	
174	            for (int brokerId : cluster.brokerIds()) {
175	                TestUtils.waitForCondition(() -> {
176	                    Map<String, LogDirDescription> descriptions = logDirs(admin, brokerId);
177	                    long replicasInCordonedDir = descriptions.get(cordoned.get(brokerId)).replicaInfos().keySet().stream()
178	                        .filter(tp -> tp.topic().equals(topic)).count();
179	                    long replicasInOtherDirs = descriptions.entrySet().stream()
180	                        .filter(e -> !e.getKey().equals(cordoned.get(brokerId)))
181	                        .flatMap(e -> e.getValue().replicaInfos().keySet().stream())
182	                        .filter(tp -> tp.topic().equals(topic)).count();
183	                    return replicasInCordonedDir == 0 && replicasInOtherDirs == 6;
184	                }, WAIT_MS, "Replicas of " + topic + " were not all placed in the uncordoned directory of broker " + brokerId);
185	            }
186	
187	            // Removing the config uncordons the directories again.
188	            uncordon(admin, 0);
189	            waitForCordoned(admin, 0, Set.of());
190	            waitForCordoned(admin, 1, Set.of(cordoned.get(1)));
191	
192	            // The cordoned state can also be changed by replacing the value.
193	            setCordoned(admin, 0, ServerLogConfigs.CORDONED_LOG_DIRS_ALL);
194	            waitForCordoned(admin, 0, new HashSet<>(sortedLogDirs(admin, 0)));
195	        }
196	    }
197	
198	    @ClusterTest
199	    public void testBrokerWithAllLogDirectoriesCordonedReceivesNoNewPartitions() throws Exception {
200	        try (Admin admin = cluster.admin()) {
201	            setCordoned(admin, 2, ServerLogConfigs.CORDONED_LOG_DIRS_ALL);
202	            waitForCordoned(admin, 2, new HashSet<>(sortedLogDirs(admin, 2)));
203	            waitForControllerToExcludeBroker(admin, 3);
204	
205	            // Auto placement only uses the other brokers.
206	            String topic = newTopicName();
207	            admin.createTopics(List.of(new NewTopic(topic, 6, (short) 2))).all().get();
208	            assertEquals(Set.of(0, 1), replicaBrokers(admin, topic));
209	
210	            // Partitions added without assignment are not placed on the cordoned broker either.
211	            admin.createPartitions(Map.of(topic, NewPartitions.increaseTo(12))).all().get();
212	            assertEquals(Set.of(0, 1), replicaBrokers(admin, topic));
213	
214	            // Explicit assignments to the cordoned broker are invalid.
215	            assertCause(InvalidReplicaAssignmentException.class, () -> admin.createTopics(List.of(
216	                new NewTopic(newTopicName(), Map.of(0, List.of(0, 2))))).all().get());
217	            assertCause(InvalidReplicaAssignmentException.class, () -> admin.createPartitions(Map.of(
218	                topic, NewPartitions.increaseTo(13, List.of(List.of(0, 2))))).all().get());
219	
220	            // Moving a replica to the cordoned broker is ineligible.
221	            String reassigned = newTopicName();
222	            admin.createTopics(List.of(new NewTopic(reassigned, Map.of(0, List.of(0))))).all().get();
223	            assertCause(IneligibleReplicaException.class, () -> admin.alterPartitionReassignments(Map.of(
224	                new TopicPartition(reassigned, 0), Optional.of(new NewPartitionReassignment(List.of(2))))).all().get());
225	
226	            // Reassignments between the other brokers are still possible.
227	            admin.alterPartitionReassignments(Map.of(
228	                new TopicPartition(reassigned, 0), Optional.of(new NewPartitionReassignment(List.of(1))))).all().get();
229	
230	            // Uncordoning makes the broker eligible again.
231	            uncordon(admin, 2);
232	            waitForCordoned(admin, 2, Set.of());
233	            TestUtils.waitForCondition(() -> {
234	                String name = newTopicName();
235	                return createTopicError(admin, new NewTopic(name, 1, (short) 3)) == null;
236	            }, WAIT_MS, "The controller kept excluding the uncordoned broker");
237	        }
238	    }
239	
240	    @ClusterTest(serverProperties = {
241	        @ClusterConfigProperty(id = 1, key = ServerLogConfigs.CORDONED_LOG_DIRS_CONFIG, value = ServerLogConfigs.CORDONED_LOG_DIRS_ALL)
242	    })
243	    public void testStaticallyCordonedBroker() throws Exception {
244	        try (Admin admin = cluster.admin()) {
245	            waitForCordoned(admin, 1, new HashSet<>(sortedLogDirs(admin, 1)));
246	            assertEquals(Set.of(), cordonedLogDirs(admin, 0));
247	            waitForControllerToExcludeBroker(admin, 3);
248	        }
249	    }
250	
251	    @ClusterTest
252	    public void testAlterReplicaLogDirsToCordonedDirectory() throws Exception {
253	        try (Admin admin = cluster.admin()) {
254	            String topic = newTopicName();
255	            admin.createTopics(List.of(new NewTopic(topic, Map.of(0, List.of(0))))).all().get();
256	            cluster.waitTopicCreation(topic, 1);
257	            TopicPartition tp = new TopicPartition(topic, 0);
258	            TopicPartitionReplica replica = new TopicPartitionReplica(topic, 0, 0);
259	
260	            TestUtils.waitForCondition(() -> logDirs(admin, 0).values().stream()
261	                .anyMatch(d -> d.replicaInfos().containsKey(tp)), WAIT_MS, "The replica was not created");
262	            String currentDir = logDirs(admin, 0).entrySet().stream()
263	                .filter(e -> e.getValue().replicaInfos().containsKey(tp))
264	                .map(Map.Entry::getKey).findFirst().orElseThrow();
265	            String otherDir = sortedLogDirs(admin, 0).stream().filter(d -> !d.equals(currentDir)).findFirst().orElseThrow();
266	
267	            setCordoned(admin, 0, otherDir);
268	            waitForCordoned(admin, 0, Set.of(otherDir));
269	            assertCause(InvalidReplicaAssignmentException.class,
270	                () -> admin.alterReplicaLogDirs(Map.of(replica, otherDir)).all().get());
271	
272	            // Once the directory is uncordoned the replica can be moved to it.
273	            uncordon(admin, 0);
274	            waitForCordoned(admin, 0, Set.of());
275	            admin.alterReplicaLogDirs(Map.of(replica, otherDir)).all().get();
276	            TestUtils.waitForCondition(() -> logDirs(admin, 0).get(otherDir).replicaInfos().containsKey(tp)
277	                && !logDirs(admin, 0).get(currentDir).replicaInfos().containsKey(tp),
278	                WAIT_MS, "The replica was not moved to the uncordoned directory");
279	        }
280	    }
281	
282	    @ClusterTest
283	    public void testInvalidCordonedLogDirsAreRejected() throws Exception {
284	        try (Admin admin = cluster.admin()) {
285	            // Not one of the log directories of the broker.
286	            assertCause(InvalidRequestException.class, () -> setCordoned(admin, 0, "/not/a/log/dir"));
287	            // A cordoned directory of another broker.
288	            String otherBrokerDir = sortedLogDirs(admin, 1).get(0);
289	            assertCause(InvalidRequestException.class, () -> setCordoned(admin, 0, otherBrokerDir));
290	            // The config is per broker, it can't be set cluster wide.
291	            assertCause(InvalidRequestException.class, () -> admin.incrementalAlterConfigs(Map.of(
292	                new ConfigResource(ConfigResource.Type.BROKER, ""), List.of(new AlterConfigOp(
293	                    new ConfigEntry(ServerLogConfigs.CORDONED_LOG_DIRS_CONFIG, ServerLogConfigs.CORDONED_LOG_DIRS_ALL),
294	                    AlterConfigOp.OpType.SET)))).all().get());
295	            assertEquals(Set.of(), cordonedLogDirs(admin, 0));
296	
297	            // Several valid directories can be cordoned at once.
298	            List<String> dirs = sortedLogDirs(admin, 0);
299	            setCordoned(admin, 0, String.join(",", dirs));
300	            waitForCordoned(admin, 0, new HashSet<>(dirs));
301	        }
302	    }
303	
304	    @ClusterTest(metadataVersion = MetadataVersion.IBP_4_2_IV1, serverProperties = {
305	        @ClusterConfigProperty(key = ServerLogConfigs.CORDONED_LOG_DIRS_CONFIG, value = ServerLogConfigs.CORDONED_LOG_DIRS_ALL)
306	    })
307	    public void testCordoningRequiresMetadataVersion() throws Exception {
308	        try (Admin admin = cluster.admin()) {
309	            // Setting the config dynamically is rejected.
310	            String dir = sortedLogDirs(admin, 0).get(0);
311	            assertCause(InvalidConfigurationException.class, () -> setCordoned(admin, 0, dir));
312	
313	            // The statically configured value has no effect.
314	            for (int brokerId : cluster.brokerIds()) {
315	                assertEquals(Set.of(), cordonedLogDirs(admin, brokerId));
316	            }
317	            admin.createTopics(List.of(new NewTopic(newTopicName(), 3, (short) 3))).all().get();
318	
319	            // Removing the config is not a problem.
320	            uncordon(admin, 0);
321	        }
322	    }
323	
324	    @ClusterTest
325	    public void testBrokerDoesNotCreateReplicaInCordonedDirectory() throws Exception {
326	        try (Admin admin = cluster.admin()) {
327	            KafkaBroker broker = cluster.brokers().get(0);
328	            LogManager logManager = broker.logManager();
329	            List<String> dirs = sortedLogDirs(admin, 0);
330	            String cordonedDir = dirs.get(0);
331	            String uncordonedDir = dirs.get(1);
332	
333	            setCordoned(admin, 0, cordonedDir);
334	            waitForCordoned(admin, 0, Set.of(cordonedDir));
335	            TestUtils.waitForCondition(() -> logManager.isCordoned(cordonedDir), WAIT_MS, "The log manager did not cordon the directory");
336	
337	            // Even when the cordoned directory is the one suggested by the controller, a new replica is not created in it.
338	            Uuid cordonedDirId = logManager.directoryId(cordonedDir).get();
339	            for (int i = 0; i < 4; i++) {
340	                UnifiedLog log = logManager.getOrCreateLog(new TopicPartition("synthetic", i), true, false,
341	                    Optional.of(Uuid.randomUuid()), Option.apply(cordonedDirId));
342	                assertEquals(uncordonedDir, log.parentDir());
343	            }
344	
345	            // When all the directories are cordoned the broker has to pick one of them anyway.
346	            setCordoned(admin, 0, ServerLogConfigs.CORDONED_LOG_DIRS_ALL);
347	            waitForCordoned(admin, 0, new HashSet<>(dirs));
348	            UnifiedLog log = logManager.getOrCreateLog(new TopicPartition("synthetic", 10), true, false,
349	                Optional.of(Uuid.randomUuid()), Option.empty());
350	            assertTrue(dirs.contains(log.parentDir()));
351	        }
352	    }
353	
354	    @ClusterTest(brokers = 1)
355	    public void testCordonedLogDirectoryMetrics() throws Exception {
356	        try (Admin admin = cluster.admin()) {
357	            List<String> dirs = sortedLogDirs(admin, 0);
358	            assertEquals(2, dirs.size());
359	            assertEquals(0, cordonedCount());
360	            for (String dir : dirs) {
361	                assertEquals(0, cordonedGauge(dir));
362	            }
363	
364	            setCordoned(admin, 0, dirs.get(0));
365	            TestUtils.waitForCondition(() -> cordonedCount() == 1 && cordonedGauge(dirs.get(0)) == 1 && cordonedGauge(dirs.get(1)) == 0,
366	                WAIT_MS, "The metrics did not reflect one cordoned directory");
367	
368	            setCordoned(admin, 0, ServerLogConfigs.CORDONED_LOG_DIRS_ALL);
369	            TestUtils.waitForCondition(() -> cordonedCount() == 2 && cordonedGauge(dirs.get(0)) == 1 && cordonedGauge(dirs.get(1)) == 1,
370	                WAIT_MS, "The metrics did not reflect two cordoned directories");
371	
372	            uncordon(admin, 0);
373	            TestUtils.waitForCondition(() -> cordonedCount() == 0 && cordonedGauge(dirs.get(0)) == 0 && cordonedGauge(dirs.get(1)) == 0,
374	                WAIT_MS, "The metrics did not reflect that no directory is cordoned");
375	        }
376	    }
377	
378	    @ClusterTest(brokers = 1)
379	    public void testDescribeLogDirsReportsCordonedState() throws Exception {
380	        try (Admin admin = cluster.admin()) {
381	            List<String> dirs = sortedLogDirs(admin, 0);
382	            assertFalse(logDirs(admin, 0).get(dirs.get(0)).isCordoned());
383	            assertFalse(logDirs(admin, 0).get(dirs.get(1)).isCordoned());
384	
385	            setCordoned(admin, 0, dirs.get(1));
386	            waitForCordoned(admin, 0, Set.of(dirs.get(1)));
387	            assertFalse(logDirs(admin, 0).get(dirs.get(0)).isCordoned());
388	            assertTrue(logDirs(admin, 0).get(dirs.get(1)).isCordoned());
389	            assertTrue(logDirs(admin, 0).get(dirs.get(1)).toString().contains("isCordoned=true"));
390	        }
391	    }
392	
393	    private static Gauge<?> yammerGauge(String namePrefix, String suffix) {
394	        Collection<Gauge<?>> matches = new ArrayList<>();
395	        for (Map.Entry<MetricName, com.yammer.metrics.core.Metric> entry : KafkaYammerMetrics.defaultRegistry().allMetrics().entrySet()) {
396	            String mbeanName = entry.getKey().getMBeanName();
397	            if (mbeanName.startsWith(namePrefix) && mbeanName.endsWith(suffix)) {
398	                matches.add((Gauge<?>) entry.getValue());
399	            }
400	        }
401	        assertEquals(1, matches.size(), "Expected exactly one metric " + namePrefix + "..." + suffix);
402	        return matches.iterator().next();
403	    }
404	
405	    private static int cordonedCount() {
406	        return ((Number) yammerGauge("kafka.log:type=LogManager,name=CordonedLogDirectoryCount", "").value()).intValue();
407	    }
408	
409	    private static int cordonedGauge(String dir) {
410	        return ((Number) yammerGauge("kafka.log:type=LogManager,name=LogDirectoryCordoned,", "logDirectory=" + Sanitizer.jmxSanitize(dir)).value()).intValue();
411	    }
412	}
