package org.apache.kafka.controller;

import org.apache.kafka.common.Uuid;
import org.apache.kafka.common.metadata.BrokerRegistrationChangeRecord;
import org.apache.kafka.metadata.BrokerRegistration;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class aih_probe_cordon_test {
    @Test
    public void testOfflineAndCordonedMix() {
        Uuid a = Uuid.randomUuid();
        Uuid b = Uuid.randomUuid();
        BrokerRegistration r = new BrokerRegistration.Builder().setId(1).setEpoch(1)
            .setIncarnationId(Uuid.randomUuid()).setDirectories(List.of(a, b))
            .setCordonedDirectories(List.of(a)).build();
        assertTrue(r.hasUncordonedDir());
        BrokerRegistration r2 = r.cloneWith(java.util.Optional.empty(), java.util.Optional.empty(),
            java.util.Optional.empty(), java.util.Optional.of(List.of(b, a)));
        assertFalse(r2.hasUncordonedDir());
        BrokerRegistrationChangeRecord rec = new BrokerRegistrationChangeRecord();
        assertTrue(rec.cordonedLogDirs() == null);
    }
}

